"use client";

import { useEffect } from "react";
import { useChatStore } from "@/store/useChatStore";
import {
  getActiveChats,
  getConversation,
  createNotification,
  markChatAsRead,
} from "@/actions/notification";
import { useUser } from "@clerk/nextjs";
import { Search, Send, Loader2, MessageSquare } from "lucide-react";

export default function ChatAdminView() {
  const { user: currentUser } = useUser();
  const {
    chats,
    setChats,
    activeChatId,
    setActiveChat,
    messages,
    setMessages,
    addMessage,
    isLoading,
    setIsLoading,
    markAsReadInStore,
  } = useChatStore();

  // 1. Загружаем список чатов (с сортировкой по непрочитанным)
  useEffect(() => {
    const fetchList = async () => {
      const data = await getActiveChats();
      setChats(data);
    };
    fetchList();
  }, [setChats]);

  // 2. Загружаем переписку при выборе человека
  useEffect(() => {
    if (activeChatId && currentUser) {
      const fetchMessages = async () => {
        setIsLoading(true);
        const data = await getConversation(currentUser.id, activeChatId);
        const validMessages = data.filter((msg) => msg.senderId !== null);
        setMessages(validMessages as any);
        setIsLoading(false);
      };
      fetchMessages();
    }
  }, [activeChatId, currentUser, setMessages, setIsLoading]);

  // 3. Обработка клика по чату (сброс счетчика)
  const handleSelectChat = async (userId: string) => {
    setActiveChat(userId);
    markAsReadInStore(userId); // Мгновенно убираем красный кружок в интерфейсе
    await markChatAsRead(userId); // В фоне отмечаем прочитанным в БД
  };

  // 4. Отправка сообщения
  const onSend = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const text = formData.get("message") as string;
    if (!text.trim() || !activeChatId || !currentUser) return;

    e.currentTarget.reset();

    // Оптимистичное добавление в стор (чтобы сообщение появилось сразу)
    const tempMsg = {
      id: Math.random().toString(),
      senderId: currentUser.id,
      userId: activeChatId,
      message: text.trim(),
      createdAt: new Date(),
    };
    addMessage(tempMsg as any);

    // Отправляем в базу
    await createNotification(
      activeChatId,
      "Ответ админа",
      text.trim(),
      "/dashboard/chat",
      currentUser.id,
      "crm_personal",
    );
  };

  return (
    <div className="flex h-[calc(100vh-120px)] bg-white rounded-[32px] shadow-sm border border-gray-100 overflow-hidden mt-4">
      {/* ЛЕВАЯ КОЛОНКА: Список пользователей */}
      <div className="w-80 border-r border-gray-100 flex flex-col bg-gray-50/20">
        <div className="p-6 bg-white border-b border-gray-50 shrink-0">
          <h2 className="text-2xl font-black text-gray-900 mb-4">Чаты</h2>
          <div className="relative">
            <Search
              className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              size={16}
            />
            <input
              placeholder="Найти клиента..."
              className="w-full pl-10 pr-4 py-2.5 bg-gray-100 rounded-xl text-sm outline-none focus:ring-2 ring-indigo-500 transition-all"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {chats.length === 0 ? (
            <p className="p-8 text-center text-xs text-gray-400 font-bold uppercase tracking-widest">
              Нет активных диалогов
            </p>
          ) : (
            chats.map((u) => {
              const hasUnread = u.unreadCount && u.unreadCount > 0;
              const isActive = activeChatId === u.id;

              return (
                <button
                  key={u.id}
                  onClick={() => handleSelectChat(u.id)}
                  className={`w-full p-4 flex items-center gap-4 transition-all border-l-4 ${
                    isActive
                      ? "bg-white border-indigo-600 shadow-sm"
                      : "border-transparent hover:bg-gray-100/50"
                  }`}
                >
                  <div className="relative shrink-0">
                    <img
                      src={u.imageUrl || "/default-avatar.png"}
                      alt=""
                      className="w-12 h-12 rounded-2xl object-cover shadow-sm bg-gray-100"
                    />
                    {/* КРАСНЫЙ БЕЙДЖИК НЕПРОЧИТАННЫХ */}
                    {hasUnread ? (
                      <div className="absolute -top-1.5 -right-1.5 bg-red-500 text-white text-[10px] font-black w-5 h-5 rounded-full flex items-center justify-center border-2 border-white shadow-sm z-10 animate-in zoom-in">
                        {u.unreadCount! > 99 ? "99+" : u.unreadCount}
                      </div>
                    ) : null}
                  </div>

                  <div className="text-left overflow-hidden flex-1">
                    <p
                      className={`font-bold truncate ${hasUnread ? "text-gray-900" : "text-gray-700"}`}
                    >
                      {u.firstName} {u.lastName}
                    </p>
                    <p
                      className={`text-[10px] uppercase font-bold mt-0.5 truncate ${hasUnread ? "text-indigo-600" : "text-gray-400"}`}
                    >
                      {hasUnread ? "Новое сообщение" : "Нажмите, чтобы открыть"}
                    </p>
                  </div>
                </button>
              );
            })
          )}
        </div>
      </div>

      {/* ПРАВАЯ КОЛОНКА: Окно переписки */}
      <div className="flex-1 flex flex-col bg-white relative">
        {activeChatId ? (
          <>
            {/* Шапка чата */}
            <div className="p-5 border-b border-gray-50 flex items-center gap-3 bg-white/80 backdrop-blur-md sticky top-0 z-10 shrink-0">
              <div className="w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.5)]" />
              <span className="font-bold text-gray-700">
                Переписка с клиентом
              </span>
            </div>

            {/* Область сообщений */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-gray-50/30">
              {isLoading ? (
                <div className="h-full flex items-center justify-center">
                  <Loader2 className="animate-spin text-indigo-500" size={32} />
                </div>
              ) : messages.length === 0 ? (
                <div className="h-full flex items-center justify-center text-gray-400 font-medium text-sm">
                  Здесь пока нет сообщений
                </div>
              ) : (
                messages.map((m) => {
                  const isAdmin = m.senderId === currentUser?.id;
                  return (
                    <div
                      key={m.id}
                      className={`flex ${isAdmin ? "justify-end" : "justify-start"}`}
                    >
                      <div
                        className={`max-w-[75%] p-4 rounded-2xl text-sm shadow-sm ${
                          isAdmin
                            ? "bg-gray-900 text-white rounded-tr-none"
                            : "bg-white border border-gray-100 text-gray-800 rounded-tl-none"
                        }`}
                      >
                        <p className="leading-relaxed whitespace-pre-wrap">
                          {m.message}
                        </p>
                        <p
                          className={`text-[9px] mt-2 text-right ${isAdmin ? "opacity-40" : "text-gray-400"}`}
                        >
                          {new Date(m.createdAt).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </p>
                      </div>
                    </div>
                  );
                })
              )}
            </div>

            {/* Поле ввода */}
            <form
              onSubmit={onSend}
              className="p-6 bg-white border-t border-gray-50 flex gap-3 shrink-0"
            >
              <input
                name="message"
                placeholder="Написать ответ..."
                autoComplete="off"
                className="flex-1 bg-gray-50 border border-gray-200 rounded-2xl px-6 py-4 outline-none focus:ring-2 ring-indigo-500 transition-all shadow-inner text-sm"
              />
              <button
                type="submit"
                className="p-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 shadow-lg active:scale-95 transition-all flex items-center justify-center"
              >
                <Send size={20} className="-ml-1" />
              </button>
            </form>
          </>
        ) : (
          /* Заглушка, если чат не выбран */
          <div className="flex-1 flex flex-col items-center justify-center text-gray-400 space-y-6">
            <div className="w-24 h-24 bg-gray-50 rounded-[32px] flex items-center justify-center shadow-inner border border-gray-100">
              <MessageSquare
                size={48}
                strokeWidth={1}
                className="text-gray-300"
              />
            </div>
            <div className="text-center">
              <p className="text-xl font-bold text-gray-900 mb-1">
                Центр сообщений
              </p>
              <p className="text-sm font-medium text-gray-500">
                Выберите диалог из списка слева, чтобы начать общение
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { Calendar, Edit, Lock, ArrowRight } from "lucide-react";
import { motion } from "framer-motion";
import dayjs from "dayjs";
import "dayjs/locale/ru";
import { cn } from "@/lib/utils";

dayjs.locale("ru");

export default function EventCard({
  item,
  onEdit,
  isAdmin,
}: {
  item: any;
  onEdit: (item: any) => void;
  isAdmin: boolean;
}) {
  const { event } = item;
  const router = useRouter();
  const isClosed = event.isRegistrationClosed;
  if (!isAdmin && isClosed) return null;
  const handleClick = () => {
    if (isAdmin) onEdit(item);
    else router.push(`/events/${event.id}`);
  };

  return (
    <>
      <motion.div
        layout
        onClick={handleClick}
        className="group relative rounded-[32px] overflow-hidden aspect-[3/4] bg-neutral-100 dark:bg-neutral-900 shadow-sm transition-all duration-500 hover:shadow-2xl cursor-pointer isolate"
      >
        <img
          src={event.imageUrl || "/default-event-poster.png"}
          alt={event.title}
          className={cn(
            "absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-110 -z-10",
            isClosed && "grayscale-[30%] opacity-80",
          )}
        />
        {isAdmin && isClosed && (
          <div className="absolute top-4 left-4 z-20 px-3 py-1.5 bg-red-500/90 backdrop-blur-md rounded-full flex items-center gap-1.5 shadow-lg border border-red-400/20">
            <Lock size={12} strokeWidth={3} className="text-white" />
            <span className="text-[9px] font-black uppercase tracking-widest text-white">
              Запись закрыта
            </span>
          </div>
        )}
        {isAdmin && (
          <div className="absolute top-4 right-4 z-20 w-10 h-10 bg-white/90 dark:bg-black/90 backdrop-blur-md text-neutral-900 dark:text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-lg">
            <Edit size={16} />
          </div>
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent -z-10" />
        <div className="absolute inset-0 flex flex-col justify-end p-6 z-10">
          <div className="translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
            <p className="text-[#FFB800] text-xs font-black uppercase tracking-widest mb-2 flex items-center gap-1.5">
              <Calendar size={14} />
              {event.date
                ? dayjs(event.date).format("DD MMM YYYY")
                : "Дата не указана"}
            </p>
            <h3 className="text-white text-2xl font-black tracking-tighter leading-tight mb-4 line-clamp-3">
              {event.title}
            </h3>
            <div className="opacity-0 group-hover:opacity-100 transition-opacity duration-500 hidden md:block">
              <button className="w-full py-3.5 rounded-2xl font-bold text-sm bg-white/10 hover:bg-white/20 text-white backdrop-blur-md transition-colors border border-white/20 pointer-events-none flex items-center justify-center gap-2">
                {isAdmin ? (
                  "Редактировать событие"
                ) : (
                  <>
                    <ArrowRight size={16} /> Узнать подробности
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </motion.div>
    </>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import {
  X,
  Loader2,
  Upload,
  Image as ImageIcon,
  Plus,
  Calendar,
  MapPin,
  Users,
  Coins,
  Repeat,
  Lock,
  Link as LinkIcon,
} from "lucide-react";

import { createEvent, updateEvent, createEventCategory } from "@/actions/event";
import { useEventStore } from "@/store/useEventStore";
import { uploadEventImage } from "@/supabase/storage";

const WEEKDAYS = [
  { label: "Пн", val: 1 },
  { label: "Вт", val: 2 },
  { label: "Ср", val: 3 },
  { label: "Чт", val: 4 },
  { label: "Пт", val: 5 },
  { label: "Сб", val: 6 },
  { label: "Вс", val: 0 },
];

export default function EventModal({ isOpen, onClose, editData }: any) {
  const {
    addEvent,
    updateEvent: updateInStore,
    categories,
    addCategory,
  } = useEventStore();

  const [isSubmitting, setIsSubmitting] = useState(false);

  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [eventDate, setEventDate] = useState("");
  const [eventTime, setEventTime] = useState("");
  const [location, setLocation] = useState("");
  const [isFree, setIsFree] = useState(false);

  const [price, setPrice] = useState("");
  const [childPrice, setChildPrice] = useState(""); // 🔥 ДОБАВЛЕНО ПОЛЕ ДЛЯ ДЕТЕЙ
  const [paymentUrl, setPaymentUrl] = useState("");

  const [audience, setAudience] = useState("all");

  const [isRecurring, setIsRecurring] = useState(false);
  const [recurringPattern, setRecurringPattern] = useState("weekly");
  const [recurringDays, setRecurringDays] = useState<number[]>([]);
  const [isRegistrationClosed, setIsRegistrationClosed] = useState(false);

  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isCreatingCategory, setIsCreatingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState("");
  const [newCategoryColor, setNewCategoryColor] = useState("#FFB800");
  const [isSavingCategory, setIsSavingCategory] = useState(false);

  useEffect(() => {
    if (editData && isOpen) {
      const ev = editData.event || editData;

      setTitle(ev.title || "");
      setDescription(ev.description || "");
      setCategoryId(ev.categoryId || "");
      setEventDate(ev.date || "");
      setEventTime(ev.time || "");
      setLocation(ev.location || "");
      setIsFree(ev.isFree || false);
      setPrice(ev.price || "");
      setChildPrice(ev.childPrice || ""); // 🔥
      setPaymentUrl(ev.paymentUrl || "");
      setAudience(ev.audience || "all");
      setImagePreview(ev.imageUrl || null);
      setIsRegistrationClosed(ev.isRegistrationClosed || false);
      setIsRecurring(ev.isRecurring || false);
      setRecurringPattern(ev.recurringPattern || "weekly");
      try {
        setRecurringDays(ev.recurringDays ? JSON.parse(ev.recurringDays) : []);
      } catch (e) {
        setRecurringDays([]);
      }
      setImageFile(null);
      setIsCreatingCategory(false);
    } else {
      setTitle("");
      setDescription("");
      setCategoryId("");
      setEventDate("");
      setEventTime("");
      setLocation("");
      setIsFree(false);
      setPrice("");
      setChildPrice(""); // 🔥
      setPaymentUrl("");
      setAudience("all");
      setImagePreview(null);
      setImageFile(null);
      setIsRegistrationClosed(false);
      setIsRecurring(false);
      setRecurringPattern("weekly");
      setRecurringDays([]);
      setIsCreatingCategory(false);
    }
  }, [editData, isOpen]);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => setImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveCategory = async () => {
    if (!newCategoryName.trim()) return;
    setIsSavingCategory(true);
    try {
      const res = await createEventCategory(newCategoryName, newCategoryColor);
      if (res.success && res.id) {
        addCategory({
          id: res.id,
          name: newCategoryName,
          color: newCategoryColor,
          createdAt: new Date() as any,
        });
        setCategoryId(res.id);
        setIsCreatingCategory(false);
        setNewCategoryName("");
      }
    } catch (error) {
      console.error("Ошибка", error);
    } finally {
      setIsSavingCategory(false);
    }
  };

  const toggleRecurringDay = (dayVal: number) => {
    setRecurringDays((prev) =>
      prev.includes(dayVal)
        ? prev.filter((d) => d !== dayVal)
        : [...prev, dayVal],
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const ev = editData?.event || editData;
    let finalImageUrl = ev?.imageUrl || "";

    if (imageFile) {
      try {
        const uploadedUrl = await uploadEventImage(imageFile);
        if (uploadedUrl) finalImageUrl = uploadedUrl;
      } catch (error) {
        alert("Не удалось загрузить картинку.");
        setIsSubmitting(false);
        return;
      }
    }

    const data = {
      title,
      description,
      categoryId,
      date: eventDate,
      time: eventTime,
      location,
      isFree,
      price: isFree ? "" : price,
      childPrice: isFree ? "" : childPrice, // 🔥 СОХРАНЯЕМ ЦЕНУ РЕБЕНКА
      paymentUrl: isFree ? "" : paymentUrl,
      audience,
      imageUrl: finalImageUrl,
      isRegistrationClosed,
      isRecurring,
      recurringPattern: isRecurring ? recurringPattern : null,
      recurringDays:
        isRecurring && recurringPattern === "weekly"
          ? JSON.stringify(recurringDays)
          : null,
    };

    if (editData) {
      await updateEvent(ev.id, data);
      updateInStore(ev.id, {
        event: {
          id: ev.id,
          ...ev,
          ...data,
        } as any,
        category: categories.find((c) => c.id === categoryId) || null,
      });
    } else {
      const res = await createEvent(data);
      if (res.success) {
        addEvent({
          event: {
            id: res.id,
            status: "planned",
            createdAt: new Date(),
            ...data,
          } as any,
          category: categories.find((c) => c.id === categoryId) || null,
        });
      }
    }

    setIsSubmitting(false);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-2 sm:p-4 transition-opacity duration-300">
      <div className="bg-white rounded-2xl sm:rounded-[32px] shadow-2xl w-full max-w-3xl overflow-hidden flex flex-col max-h-[95vh] sm:max-h-[90vh] transition-transform duration-300 scale-100">
        <div className="p-4 sm:p-6 border-b flex justify-between items-center bg-neutral-50/50 flex-shrink-0">
          <h2 className="text-xl sm:text-2xl font-black text-neutral-900 tracking-tight line-clamp-1">
            {editData ? "Редактировать событие" : "Создать событие"}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-neutral-200 rounded-full transition-colors text-neutral-500 hover:text-black flex-shrink-0"
          >
            <X size={20} />
          </button>
        </div>

        <form
          onSubmit={handleSubmit}
          className="p-4 sm:p-6 overflow-y-auto space-y-5 sm:space-y-6 flex-1 custom-scrollbar"
        >
          {/* ОБЛОЖКА */}
          <div>
            <label className="block text-sm font-bold text-neutral-700 mb-2">
              Обложка афиши
            </label>
            <div
              onClick={() => fileInputRef.current?.click()}
              className={`
                relative w-full h-40 sm:h-56 rounded-2xl sm:rounded-3xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer overflow-hidden transition-all group
                ${imagePreview ? "border-[#FFB800]" : "border-neutral-300 hover:border-[#FFB800] hover:bg-[#FFB800]/5"}
              `}
            >
              {imagePreview ? (
                <>
                  <img
                    src={imagePreview}
                    alt="Preview"
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                    <span className="text-white font-bold text-xs sm:text-sm flex items-center gap-2 bg-black/50 px-4 sm:px-5 py-2 sm:py-2.5 rounded-full backdrop-blur-md">
                      <Upload size={16} className="sm:size-[18px]" /> Заменить
                      афишу
                    </span>
                  </div>
                </>
              ) : (
                <div className="text-center p-4 sm:p-6">
                  <div className="w-10 h-10 sm:w-14 sm:h-14 bg-neutral-100 rounded-full flex items-center justify-center mx-auto mb-2 sm:mb-3 text-neutral-400 group-hover:text-[#FFB800] group-hover:bg-[#FFB800]/10 transition-colors">
                    <ImageIcon size={24} className="sm:size-[28px]" />
                  </div>
                  <p className="text-xs sm:text-sm font-bold text-neutral-700">
                    Нажмите для загрузки
                  </p>
                  <p className="text-[10px] sm:text-xs text-neutral-400 mt-1">
                    Рекомендуем вертикальную
                  </p>
                </div>
              )}
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleImageChange}
                accept="image/*"
                className="hidden"
              />
            </div>
          </div>

          {/* НАЗВАНИЕ */}
          <div>
            <label className="block text-sm font-bold text-neutral-700 mb-2">
              Название события *
            </label>
            <input
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full border-2 border-neutral-200 p-3 sm:p-4 rounded-xl sm:rounded-2xl outline-none focus:border-[#FFB800] transition-colors text-sm sm:text-base"
              placeholder="Напр: Большой хасидский фарбренген"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5 sm:gap-6">
            <div className="space-y-3 sm:space-y-4">
              <label className="block text-sm font-bold text-neutral-700">
                Когда?
              </label>
              <div className="grid grid-cols-1 xs:grid-cols-[1fr,auto] gap-2">
                <div className="relative">
                  <Calendar
                    size={18}
                    className="absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-400"
                  />
                  <input
                    required
                    type="date"
                    value={eventDate}
                    onChange={(e) => setEventDate(e.target.value)}
                    className="w-full border-2 border-neutral-200 p-3 pl-10 rounded-xl sm:rounded-2xl outline-none focus:border-[#FFB800] text-sm"
                  />
                </div>
                <div className="relative xs:w-28">
                  <input
                    required
                    type="time"
                    value={eventTime}
                    onChange={(e) => setEventTime(e.target.value)}
                    className="w-full border-2 border-neutral-200 p-3 rounded-xl sm:rounded-2xl outline-none focus:border-[#FFB800] text-sm"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-3 sm:space-y-4">
              <label className="block text-sm font-bold text-neutral-700">
                Где?
              </label>
              <div className="relative">
                <MapPin
                  size={18}
                  className="absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-400"
                />
                <input
                  value={location}
                  onChange={(e) => setLocation(e.target.value)}
                  className="w-full border-2 border-neutral-200 p-3 pl-10 rounded-xl sm:rounded-2xl outline-none focus:border-[#FFB800] text-sm"
                  placeholder="Адрес или ссылка на Zoom"
                />
              </div>
            </div>

            {/* БЛОК ЦИКЛИЧНОСТИ */}
            <div className="col-span-1 md:col-span-2 bg-neutral-50 p-4 sm:p-5 rounded-2xl sm:rounded-3xl border border-neutral-100 transition-all duration-300">
              <label className="flex items-center gap-3 cursor-pointer group w-max">
                <input
                  type="checkbox"
                  checked={isRecurring}
                  onChange={(e) => setIsRecurring(e.target.checked)}
                  className="w-5 h-5 rounded border-neutral-300 text-[#FFB800] focus:ring-[#FFB800] cursor-pointer"
                />
                <span className="text-sm font-bold text-neutral-800 group-hover:text-black flex items-center gap-1.5 transition-colors">
                  <Repeat size={16} className="text-[#FFB800]" /> Повторяющееся
                  событие (Урок)
                </span>
              </label>

              {isRecurring && (
                <div className="mt-4 space-y-4 animate-in fade-in slide-in-from-top-2">
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={() => setRecurringPattern("daily")}
                      className={`flex-1 py-2.5 rounded-xl text-sm font-bold transition-all ${
                        recurringPattern === "daily"
                          ? "bg-[#FFB800] text-black shadow-md"
                          : "bg-white border-2 border-neutral-200 text-neutral-500 hover:border-neutral-300"
                      }`}
                    >
                      Каждый день
                    </button>
                    <button
                      type="button"
                      onClick={() => setRecurringPattern("weekly")}
                      className={`flex-1 py-2.5 rounded-xl text-sm font-bold transition-all ${
                        recurringPattern === "weekly"
                          ? "bg-[#FFB800] text-black shadow-md"
                          : "bg-white border-2 border-neutral-200 text-neutral-500 hover:border-neutral-300"
                      }`}
                    >
                      По дням недели
                    </button>
                  </div>

                  {recurringPattern === "weekly" && (
                    <div className="flex flex-wrap gap-2 pt-2">
                      {WEEKDAYS.map((day) => (
                        <button
                          key={day.val}
                          type="button"
                          onClick={() => toggleRecurringDay(day.val)}
                          className={`w-10 h-10 rounded-full text-sm font-bold transition-all ${
                            recurringDays.includes(day.val)
                              ? "bg-black text-white shadow-md scale-110"
                              : "bg-white border-2 border-neutral-200 text-neutral-500 hover:border-neutral-300 hover:bg-neutral-100"
                          }`}
                        >
                          {day.label}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6 bg-neutral-50 p-4 sm:p-5 rounded-2xl sm:rounded-3xl border border-neutral-100 items-start">
            {/* БЛОК СТОИМОСТИ И ССЫЛКИ НА ОПЛАТУ */}
            <div className="flex flex-col space-y-3">
              <label className="block text-sm font-bold text-neutral-700 flex items-center gap-2">
                <Coins size={16} className="text-[#FFB800]" /> Стоимость и
                оплата
              </label>

              <div
                className={`flex flex-col gap-3 transition-all duration-300 ease-in-out ${isFree ? "max-h-0 opacity-0 overflow-hidden" : "max-h-48 opacity-100"}`}
              >
                <div className="flex gap-2">
                  <input
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    disabled={isFree}
                    className="w-full border-2 border-neutral-200 p-3 rounded-xl outline-none focus:border-[#FFB800] text-sm transition-colors disabled:bg-neutral-100"
                    placeholder="Взрослые (₪)"
                  />
                  {/* 🔥 ИНПУТ ДЛЯ ЦЕНЫ ДЕТЕЙ */}
                  <input
                    value={childPrice}
                    onChange={(e) => setChildPrice(e.target.value)}
                    disabled={isFree}
                    className="w-full border-2 border-neutral-200 p-3 rounded-xl outline-none focus:border-[#FFB800] text-sm transition-colors disabled:bg-neutral-100"
                    placeholder="Дети (₪)"
                  />
                </div>

                {/* ИНПУТ ДЛЯ ССЫЛКИ ШУТАФИМ */}
                <div className="relative">
                  <LinkIcon
                    size={16}
                    className="absolute left-3.5 top-1/2 -translate-y-1/2 text-neutral-400"
                  />
                  <input
                    value={paymentUrl}
                    onChange={(e) => setPaymentUrl(e.target.value)}
                    disabled={isFree}
                    className="w-full border-2 border-neutral-200 p-3 pl-10 rounded-xl outline-none focus:border-[#FFB800] text-sm transition-colors disabled:bg-neutral-100"
                    placeholder="Ссылка на оплату (Shutafim)"
                  />
                </div>
              </div>

              <div className="flex items-center gap-3">
                <label className="flex items-center gap-2.5 cursor-pointer group mt-2">
                  <input
                    type="checkbox"
                    checked={isFree}
                    onChange={(e) => setIsFree(e.target.checked)}
                    className="w-5 h-5 rounded border-neutral-300 text-[#FFB800] focus:ring-[#FFB800] cursor-pointer"
                  />
                  <span className="text-sm font-medium text-neutral-800 group-hover:text-black">
                    Событие бесплатное
                  </span>
                </label>
              </div>
            </div>

            <div className="flex flex-col space-y-3">
              <label className="block text-sm font-bold text-neutral-700 flex items-center gap-2">
                <Users size={16} className="text-[#FFB800]" /> Для кого?
              </label>
              <select
                value={audience}
                onChange={(e) => setAudience(e.target.value)}
                className="w-full border-2 border-neutral-200 p-3 rounded-xl outline-none focus:border-[#FFB800] bg-white cursor-pointer text-sm"
              >
                <option value="all">Для всех</option>
                <option value="men">Только для мужчин</option>
                <option value="women">Только для женщин</option>
                <option value="kids">Для детей</option>
              </select>
            </div>
          </div>

          <div className="bg-red-50/50 p-4 sm:p-5 rounded-2xl sm:rounded-3xl border border-red-100 transition-all duration-300">
            <label className="flex items-center gap-3 cursor-pointer group w-max">
              <input
                type="checkbox"
                checked={isRegistrationClosed}
                onChange={(e) => setIsRegistrationClosed(e.target.checked)}
                className="w-5 h-5 rounded border-red-300 text-red-500 focus:ring-red-500 cursor-pointer"
              />
              <span className="text-sm font-bold text-red-700 group-hover:text-red-900 flex items-center gap-1.5 transition-colors">
                <Lock size={16} className="text-red-500" /> Закрыть регистрацию
                на событие
              </span>
            </label>
            {isRegistrationClosed && (
              <p className="text-xs text-red-600/80 mt-2 ml-8 animate-in fade-in">
                Пользователи увидят плашку «Запись закрыта» на сайте и не смогут
                зарегистрироваться.
              </p>
            )}
          </div>

          <div>
            <label className="block text-sm font-bold text-neutral-700 mb-2">
              Категория (Тег на карточке)
            </label>
            {!isCreatingCategory ? (
              <div className="flex gap-2">
                <select
                  value={categoryId}
                  onChange={(e) => setCategoryId(e.target.value)}
                  className="flex-1 border-2 border-neutral-200 rounded-xl p-3 outline-none focus:border-[#FFB800] bg-white cursor-pointer text-sm"
                >
                  <option value="">Выберите категорию...</option>
                  {categories.map((cat) => (
                    <option key={cat.id} value={cat.id}>
                      {cat.name}
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  onClick={() => setIsCreatingCategory(true)}
                  className="px-3.5 py-2 bg-neutral-100 hover:bg-neutral-200 rounded-xl font-bold text-xs sm:text-sm transition-colors border border-neutral-200 flex items-center gap-1.5 flex-shrink-0"
                >
                  <Plus size={16} />{" "}
                  <span className="hidden xs:inline">Создать</span>
                </button>
              </div>
            ) : (
              <div className="flex flex-wrap items-center gap-2 p-2.5 bg-[#FFB800]/10 border border-[#FFB800]/30 rounded-xl transition-all duration-300">
                <input
                  type="color"
                  value={newCategoryColor}
                  onChange={(e) => setNewCategoryColor(e.target.value)}
                  className="w-9 h-9 rounded cursor-pointer border-0 p-0 bg-transparent flex-shrink-0"
                  title="Цвет категории"
                />
                <input
                  type="text"
                  placeholder="Название..."
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                  className="flex-1 min-w-[120px] border-2 border-neutral-200 p-2 rounded-lg outline-none focus:border-[#FFB800] text-sm"
                  autoFocus
                />
                <div className="flex gap-1.5 ml-auto">
                  <button
                    type="button"
                    onClick={handleSaveCategory}
                    className="px-3 py-2 bg-black text-white rounded-lg text-xs font-bold disabled:opacity-50"
                  >
                    {isSavingCategory ? (
                      <Loader2 size={14} className="animate-spin" />
                    ) : (
                      "Сохранить"
                    )}
                  </button>
                  <button
                    type="button"
                    onClick={() => setIsCreatingCategory(false)}
                    className="px-2.5 py-2 text-neutral-500 font-medium text-xs hover:bg-neutral-100 rounded-lg"
                  >
                    Отмена
                  </button>
                </div>
              </div>
            )}
          </div>

          <div>
            <label className="block text-sm font-bold text-neutral-700 mb-2">
              Описание события
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full border-2 border-neutral-200 p-3 sm:p-4 rounded-xl sm:rounded-2xl outline-none focus:border-[#FFB800] min-h-[100px] sm:min-h-[120px] resize-none text-sm"
              placeholder="Расскажите подробнее о мероприятии..."
            />
          </div>

          <div className="pt-3 sm:pt-4 border-t border-neutral-100 flex-shrink-0">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full py-4 sm:py-5 bg-[#FFB800] hover:bg-orange-500 text-black rounded-full font-black uppercase tracking-widest text-xs sm:text-sm transition-all shadow-lg shadow-[#FFB800]/20 flex justify-center items-center active:scale-[0.98] disabled:opacity-60"
            >
              {isSubmitting ? (
                <Loader2 className="animate-spin" size={20} />
              ) : (
                "Сохранить событие"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

