              <div className="mt-auto space-y-2.5 pt-4 border-t border-neutral-100 dark:border-neutral-800/50 relative z-10">
                {item.service.price > 0 && (
                  <div className="flex items-center gap-2 text-sm font-bold text-neutral-600 dark:text-neutral-400">
                    <Banknote size={16} className="text-emerald-500" />
                    {item.service.price} ₪
                  </div>
                )}
                {item.service.price === 0 && (
                  <div className="flex items-center gap-2 text-sm font-bold text-neutral-600 dark:text-neutral-400">
                    <Banknote size={16} className="text-emerald-500" />
                    Бесплатно
                  </div>
                )}
                {item.service.duration && (
                  <div className="flex items-center gap-2 text-sm font-bold text-neutral-600 dark:text-neutral-400">
                    <Clock size={16} className="text-blue-500" />
                    {item.service.duration}
                  </div>
                )}
                <div className="flex items-center gap-2 text-sm font-bold text-neutral-600 dark:text-neutral-400 pt-1">
                  <Phone size={16} className="text-[#FFB800]" />
                  <span className="opacity-80 font-medium">
                    Ваш номер:
                  </span>{" "}
                  {item.participant.phone}
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {/* Порталы */}
      {mounted && createPortal(phoneModalContent, document.body)}
      {mounted && createPortal(successModalContent, document.body)}
    </div>
  );
}

"use client";

import { useTaskStore, TaskType } from "@/store/useTaskStore";
import { useDraggable } from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";
import { Trash2, Edit2, GripVertical } from "lucide-react";
import { cn } from "@/lib/utils";

export default function KanbanCard({
  task,
  isOverlay,
}: {
  task: TaskType;
  isOverlay?: boolean;
}) {
  const { teamMembers, removeTask, setEditingTask } = useTaskStore();

  const { attributes, listeners, setNodeRef, transform, isDragging } =
    useDraggable({ id: task.id, data: { task } });

  const style =
    transform && !isOverlay
      ? {
          transform: CSS.Translate.toString(transform),
          opacity: isDragging ? 0.3 : 1,
        }
      : undefined;

  const assignee = teamMembers.find((m) => m.id === task.assigneeId);

  return (
    <div
      ref={isOverlay ? undefined : setNodeRef}
      style={style}
      className={cn(
        "group relative bg-white dark:bg-neutral-900 p-5 rounded-2xl border transition-all duration-300 outline-none",
        isOverlay
          ? "shadow-2xl shadow-[#FFB800]/20 border-[#FFB800] ring-2 ring-[#FFB800]/50 scale-105 rotate-2 z-50 cursor-grabbing"
          : "shadow-sm border-neutral-200/50 dark:border-neutral-800/50 hover:shadow-xl hover:shadow-[#FFB800]/5 hover:border-[#FFB800]/30",
      )}
    >
      {/* Кнопки управления (Появляются при наведении) */}
      {!isOverlay && (
        <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex gap-1 z-20">
          <button
            onClick={() => setEditingTask(task)}
            className="p-2 bg-neutral-100 hover:bg-white dark:bg-neutral-800 dark:hover:bg-neutral-700 rounded-xl text-neutral-500 hover:text-blue-500 transition-colors shadow-sm active:scale-95"
            title="Редактировать"
          >
            <Edit2 size={12} strokeWidth={2.5} />
          </button>
          <button
            onClick={() => removeTask(task.id)}
            className="p-2 bg-red-500/10 hover:bg-red-500/20 rounded-xl text-red-500 transition-colors shadow-sm active:scale-95"
            title="Удалить"
          >
            <Trash2 size={12} strokeWidth={2.5} />
          </button>
        </div>
      )}

      {/* Зона захвата (Drag handle) и контент */}
      <div
        {...(isOverlay ? {} : listeners)}
        {...(isOverlay ? {} : attributes)}
        className={cn(
          "w-full h-full flex flex-col outline-none",
          !isOverlay && "cursor-grab active:cursor-grabbing",
        )}
      >
        <div className="flex items-start gap-2 mb-2 pr-16">
          <GripVertical
            size={14}
            className="text-neutral-300 dark:text-neutral-700 mt-1 shrink-0"
          />
          <h4 className="font-bold text-neutral-900 dark:text-white text-sm leading-snug">
            {task.title}
          </h4>
        </div>

        {task.description && (
          <p className="text-xs text-neutral-500 dark:text-neutral-400 line-clamp-2 leading-relaxed mb-4 pl-6">
            {task.description}
          </p>
        )}

        {/* Футер карточки (Исполнитель и ID) */}
        <div className="mt-auto pt-4 border-t border-neutral-100 dark:border-neutral-800/50 flex justify-between items-center pl-6">
          <span className="text-[9px] font-black text-neutral-400 uppercase tracking-widest">
            #{task.id.slice(0, 6)}
          </span>

          {assignee ? (
            <div
              className="flex items-center gap-2"
              title={`${assignee.firstName} ${assignee.lastName}`}
            >
              <span className="text-[10px] font-bold text-neutral-600 dark:text-neutral-400 hidden sm:block">
                {assignee.firstName}
              </span>
              <img
                src={assignee.imageUrl || "/default-avatar.png"}
                alt="assignee"
                className="w-7 h-7 rounded-full object-cover border-2 border-white dark:border-neutral-900 shadow-sm"
              />
            </div>
          ) : (
            <div
              className="flex items-center justify-center w-7 h-7 rounded-full bg-neutral-100 dark:bg-neutral-800 border-2 border-white dark:border-neutral-900 shadow-sm text-neutral-400 text-[10px] font-black"
              title="Не назначен"
            >
              ?
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  Plus,
  Pencil,
  Trash2,
  Eye,
  Pin,
  Image as ImageIcon,
  Loader2,
  X,
  Tags,
  UserRound, // <-- Добавили новую иконку для автора
} from "lucide-react";
import dynamic from "next/dynamic";
import { toast } from "sonner";
import {
  createNews,
  updateNews,
  deleteNews,
  getNewsCategories,
  createNewsCategory,
  deleteNewsCategory,
} from "@/actions/news";
import { uploadImageAction } from "@/actions/news";
// @ts-ignore: side-effect CSS import without type declarations
import "react-quill-new/dist/quill.snow.css";

const ReactQuill = dynamic(() => import("react-quill-new"), { ssr: false });

export default function AdminNewsClient({
  initialNews,
  authors, // <-- Получаем список авторов
  currentUserRole, // <-- Роль текущего пользователя
}: {
  initialNews: any[];
  authors: { id: string; name: string }[];
  currentUserRole: string;
}) {
  const [newsList, setNewsList] = useState(initialNews);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);

  // Состояния для категорий
  const [categories, setCategories] = useState<any[]>([]);
  const [selectedCategoryId, setSelectedCategoryId] = useState("");
  const [newCatName, setNewCatName] = useState("");
  const [newCatDesc, setNewCatDesc] = useState("");
  const [newCatIcon, setNewCatIcon] = useState("newspaper");

  // Состояния формы новости
  const [editingId, setEditingId] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState("");
  const [isPinned, setIsPinned] = useState(false);
  const [isPublished, setIsPublished] = useState(true);
  const [targetAuthorId, setTargetAuthorId] = useState(""); // <-- Состояние для выбранного автора
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Загружаем категории при старте
  useEffect(() => {
    getNewsCategories().then(setCategories);
  }, []);

  const resetForm = () => {
    setEditingId(null);
    setTitle("");
    setContent("");
    setImageFile(null);
    setImageUrl("");
    setIsPinned(false);
    setIsPublished(true);
    setSelectedCategoryId("");
    setTargetAuthorId(""); // Сбрасываем выбранного автора
  };

  const handleEdit = (item: any) => {
    setEditingId(item.id);
    setTitle(item.title);
    setContent(item.content);
    setImageUrl(item.imageUrl || "");
    setIsPinned(item.isPinned);
    setIsPublished(item.isPublished);
    setSelectedCategoryId(item.categoryId || "");
    setTargetAuthorId(item.authorId || ""); // Подгружаем автора при редактировании
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Точно удалить новость?")) return;
    const res = await deleteNews(id);
    if (res.success) {
      toast.success("Новость удалена");
      setNewsList((prev) => prev.filter((n) => n.id !== id));
    } else {
      toast.error(res.error);
    }
  };

  const handleSubmit = async () => {
    if (!title || !content) {
      toast.error("Заполните заголовок и текст");
      return;
    }
    setIsSubmitting(true);
    let uploadedImageUrl = imageUrl;

    if (imageFile) {
      toast.loading("Загружаем обложку...");
      const formData = new FormData();
      formData.append("file", imageFile);
      const uploadRes = await uploadImageAction(formData);
      toast.dismiss();
      if (uploadRes.success && uploadRes.url) {
        uploadedImageUrl = uploadRes.url;
      } else {
        toast.error("Ошибка загрузки картинки");
        setIsSubmitting(false);
        return;
      }
    }

    const newsData = {
      title,
      content,
      imageUrl: uploadedImageUrl,
      isPinned,
      isPublished,
      categoryId: selectedCategoryId || null,
      targetAuthorId: targetAuthorId || null, // Отправляем ID выбранного автора (а не жестко "admin")
    };

    let res;
    if (editingId) {
      res = await updateNews(editingId, newsData);
    } else {
      res = await createNews(newsData);
    }

    if (res.success) {
      toast.success(editingId ? "Сохранено!" : "Опубликовано!");
      setIsModalOpen(false);
      resetForm();
      window.location.reload(); // Перезагружаем, чтобы подтянуть изменения
    } else {
      toast.error(res.error);
    }
    setIsSubmitting(false);
  };

  // --- Функции для категорий ---
  const handleCreateCategory = async () => {
    if (!newCatName) return;
    const res = await createNewsCategory({
      name: newCatName,
      description: newCatDesc,
      icon: newCatIcon,
    });
    if (res.success) {
      toast.success("Тема создана");
      setNewCatName("");
      setNewCatDesc("");
      getNewsCategories().then(setCategories);
    }
  };

  const handleDeleteCategory = async (id: string) => {
    if (!confirm("Удалить тему?")) return;
    const res = await deleteNewsCategory(id);
    if (res.success) {
      toast.success("Удалено");
      getNewsCategories().then(setCategories);
    }
  };

  return (
    <div className="bg-white dark:bg-neutral-900 rounded-[32px] p-8 border border-neutral-200 dark:border-neutral-800 shadow-sm">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-2xl font-black text-neutral-900 dark:text-white tracking-tighter">
            {currentUserRole === "author" ? "Мои статьи" : "Все статьи блога"}
          </h2>
          <p className="text-neutral-500 font-medium mt-1">
            Управление материалами
          </p>
        </div>
        <div className="flex gap-4">
          {/* Кнопка "Темы" видна только админам */}
          {(currentUserRole === "superadmin" ||
            currentUserRole === "admin") && (
            <button
              onClick={() => setIsCatModalOpen(true)}
              className="flex items-center gap-2 px-5 py-3 bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 text-neutral-900 dark:text-white rounded-full font-bold text-sm transition-all"
            >
              <Tags size={18} />
              Темы
            </button>
          )}
          <button
            onClick={() => {
              resetForm();
              setIsModalOpen(true);
            }}
            className="flex items-center gap-2 px-5 py-3 bg-[#FFB800] hover:bg-orange-500 text-black rounded-full font-bold text-sm transition-all shadow-lg shadow-[#FFB800]/20"
          >
            <Plus size={18} />
            Написать статью
          </button>
        </div>
      </div>

      {/* Список новостей */}
      <div className="space-y-4">
        {newsList.map((item) => (
          <div
            key={item.id}
            className="flex items-center justify-between p-4 rounded-2xl bg-neutral-50 dark:bg-neutral-800/50 border border-neutral-100 dark:border-neutral-800 group hover:border-[#FFB800]/50 transition-colors"
          >
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 rounded-xl bg-neutral-200 dark:bg-neutral-800 overflow-hidden flex-shrink-0">
                {item.imageUrl ? (
                  <img
                    src={item.imageUrl}
                    alt=""
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <ImageIcon className="w-full h-full p-4 text-neutral-400" />
                )}
              </div>
              <div>
                <h3 className="font-bold text-neutral-900 dark:text-white">
                  {item.title}
                </h3>
                <div className="flex gap-3 text-xs font-bold uppercase tracking-widest mt-1">
                  <span
                    className={
                      item.isPublished ? "text-green-500" : "text-neutral-400"
                    }
                  >
                    {item.isPublished ? "Опубликовано" : "Черновик"}
                  </span>
                  {item.isPinned && (
                    <span className="text-[#FFB800] flex items-center gap-1">
                      <Pin size={12} /> Важное
                    </span>
                  )}
                </div>
              </div>
            </div>
            <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <button
                onClick={() => handleEdit(item)}
                className="p-2 text-neutral-500 hover:text-[#FFB800] bg-white dark:bg-neutral-900 rounded-full shadow-sm"
              >
                <Pencil size={16} />
              </button>
              <button
                onClick={() => handleDelete(item.id)}
                className="p-2 text-neutral-500 hover:text-red-500 bg-white dark:bg-neutral-900 rounded-full shadow-sm"
              >
                <Trash2 size={16} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* МОДАЛКА НОВОСТИ */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-neutral-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-neutral-950 rounded-[32px] w-full max-w-4xl max-h-[90vh] overflow-y-auto shadow-2xl p-8 border border-neutral-200 dark:border-neutral-800">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-3xl font-black tracking-tighter">
                {editingId ? "Редактировать статью" : "Новая статья"}
              </h2>
              <button
                onClick={() => setIsModalOpen(false)}
                className="p-2 bg-neutral-100 dark:bg-neutral-800 rounded-full hover:bg-neutral-200"
              >
                <X size={20} />
              </button>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Выбор темы (Категории) */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 pl-1">
                    Тема статьи
                  </label>
                  <select
                    value={selectedCategoryId}
                    onChange={(e) => setSelectedCategoryId(e.target.value)}
                    className="w-full bg-neutral-50 dark:bg-neutral-900 border-none rounded-2xl p-4 font-bold text-neutral-900 dark:text-white outline-none focus:ring-2 focus:ring-[#FFB800]"
                  >
                    <option value="">-- Без темы --</option>
                    {categories.map((cat) => (
                      <option key={cat.id} value={cat.id}>
                        {cat.name}
                      </option>
                    ))}
                  </select>
                </div>

                {/* ВЫБОР АВТОРА (ТОЛЬКО ДЛЯ АДМИНОВ) */}
                {(currentUserRole === "superadmin" ||
                  currentUserRole === "admin") && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-neutral-400 pl-1 flex items-center gap-1">
                      <UserRound size={12} /> Публикация от лица:
                    </label>
                    <select
                      value={targetAuthorId}
                      onChange={(e) => setTargetAuthorId(e.target.value)}
                      className="w-full bg-neutral-50 dark:bg-neutral-900 border-none rounded-2xl p-4 font-bold text-neutral-900 dark:text-white outline-none focus:ring-2 focus:ring-[#FFB800]"
                    >
                      <option value="">От имени Администрации</option>
                      {authors.map((author) => (
                        <option key={author.id} value={author.id}>
                          {author.name}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
              </div>

              <input
                type="text"
                placeholder="Заголовок новости"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="w-full text-3xl font-black bg-transparent border-none outline-none placeholder:text-neutral-300 dark:placeholder:text-neutral-700"
              />

              <div className="flex gap-4 items-center p-4 bg-neutral-50 dark:bg-neutral-900 rounded-2xl">
                <div className="w-12 h-12 rounded-xl bg-[#FFB800]/20 text-[#FFB800] flex items-center justify-center">
                  <ImageIcon size={24} />
                </div>
                <div className="flex-1">
                  <p className="font-bold text-sm">Обложка статьи</p>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={(e) => setImageFile(e.target.files?.[0] || null)}
                    className="text-xs mt-1 text-neutral-500"
                  />
                </div>
              </div>

              <div className="h-[300px] rounded-2xl overflow-hidden border border-neutral-200 dark:border-neutral-800">
                <ReactQuill
                  theme="snow"
                  value={content}
                  onChange={setContent}
                  className="h-full"
                  placeholder="Напишите потрясающую статью..."
                />
              </div>

              <div className="flex gap-6 mt-10">
                <label className="flex items-center gap-3 cursor-pointer">
                  <div
                    className={`w-12 h-7 rounded-full transition-all relative ${isPinned ? "bg-[#FFB800]" : "bg-neutral-200"}`}
                    onClick={() => setIsPinned(!isPinned)}
                  >
                    <div
                      className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${isPinned ? "left-6" : "left-1"}`}
                    />
                  </div>
                  <span className="font-bold text-sm">Закрепить</span>
                </label>
                <label className="flex items-center gap-3 cursor-pointer">
                  <div
                    className={`w-12 h-7 rounded-full transition-all relative ${isPublished ? "bg-green-500" : "bg-neutral-200"}`}
                    onClick={() => setIsPublished(!isPublished)}
                  >
                    <div
                      className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${isPublished ? "left-6" : "left-1"}`}
                    />
                  </div>
                  <span className="font-bold text-sm">Опубликовать</span>
                </label>
              </div>

              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="w-full py-4 mt-8 bg-[#FFB800] text-black font-black uppercase tracking-widest rounded-2xl hover:scale-[1.02] transition-transform disabled:opacity-50"
              >
                {isSubmitting ? (
                  <Loader2 className="animate-spin mx-auto" />
                ) : (
                  "Сохранить статью"
                )}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* МОДАЛКА УПРАВЛЕНИЯ ТЕМАМИ */}
      {isCatModalOpen && (
        <div className="fixed inset-0 bg-neutral-900/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
          <div className="bg-white dark:bg-neutral-950 rounded-[32px] w-full max-w-md p-8 shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-black tracking-tighter">
                Темы новостей
              </h2>
              <button
                onClick={() => setIsCatModalOpen(false)}
                className="p-2 bg-neutral-100 dark:bg-neutral-800 rounded-full hover:bg-neutral-200"
              >
                <X size={16} />
              </button>
            </div>

            <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-2xl mb-6 space-y-3">
              <input
                type="text"
                placeholder="Название темы (напр. Праздники)"
                value={newCatName}
                onChange={(e) => setNewCatName(e.target.value)}
                className="w-full px-4 py-2 rounded-xl bg-white dark:bg-neutral-950 font-bold outline-none border border-neutral-200 dark:border-neutral-800"
              />
              <input
                type="text"
                placeholder="Краткое описание"
                value={newCatDesc}
                onChange={(e) => setNewCatDesc(e.target.value)}
                className="w-full px-4 py-2 rounded-xl bg-white dark:bg-neutral-950 text-sm outline-none border border-neutral-200 dark:border-neutral-800"
              />
              <select
                value={newCatIcon}
                onChange={(e) => setNewCatIcon(e.target.value)}
                className="w-full px-4 py-2 rounded-xl bg-white dark:bg-neutral-950 text-sm font-bold outline-none border border-neutral-200 dark:border-neutral-800"
              >
                <option value="newspaper">Иконка: Газета</option>
                <option value="users">Иконка: Люди</option>
                <option value="calendardays">Иконка: Календарь</option>
                <option value="bookheart">Иконка: Книга</option>
                <option value="scrolltext">Иконка: Свиток</option>
              </select>
              <button
                onClick={handleCreateCategory}
                className="w-full py-2 bg-[#FFB800] text-black font-bold rounded-xl text-sm hover:opacity-90"
              >
                Добавить тему
              </button>
            </div>

            <div className="space-y-2 max-h-60 overflow-y-auto">
              {categories.length === 0 ? (
                <p className="text-center text-sm text-neutral-500 py-4">
                  Нет созданных тем
                </p>
              ) : (
                categories.map((cat) => (
                  <div
                    key={cat.id}
                    className="flex justify-between items-center p-3 bg-white dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-800 rounded-xl"
                  >
                    <div>
                      <div className="font-bold text-sm">{cat.name}</div>
                      <div className="text-[10px] text-neutral-400">
                        {cat.slug}
                      </div>
                    </div>
                    <button
                      onClick={() => handleDeleteCategory(cat.id)}
                      className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition-colors"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useNewsComments } from "@/store/useNewsComments";
import { addNewsComment, deleteNewsComment } from "@/actions/news";
import { toast } from "sonner";
import { Trash2, Send, Loader2, MessageSquareOff } from "lucide-react";
import Link from "next/link";

export default function CommentsSection({
  newsId,
  initialComments,
  currentUser,
}: {
  newsId: string;
  initialComments: any[];
  currentUser: any | null;
}) {
  const { comments, setComments, addComment, removeComment } =
    useNewsComments();
  const [content, setContent] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Инициализируем Zustand начальными данными с сервера
  useEffect(() => {
    setComments(initialComments || []);
  }, [initialComments, setComments]);

  const handleSubmit = async () => {
    if (!content.trim() || !currentUser) return;
    setIsSubmitting(true);

    const tempId = Date.now().toString(); // Временный ID для моментального отображения

    // Создаем фейковый коммент для мгновенного отображения в UI
    const optimisticComment = {
      id: tempId,
      content,
      createdAt: new Date().toISOString(),
      user: currentUser, // Текущий юзер из пропсов
    };

    addComment(optimisticComment);
    setContent("");

    // Отправляем на сервер
    const res = await addNewsComment(
      newsId,
      currentUser.id,
      optimisticComment.content,
    );
    if (!res.success) {
      removeComment(tempId);
      toast.error((res as { error?: string }).error || "Произошла ошибка");
    }
    setIsSubmitting(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Удалить комментарий?")) return;
    removeComment(id); // Сразу прячем
    const res = await deleteNewsComment(id);
    if (!res.success)
      toast.error((res as { error?: string }).error || "Не удалось удалить");
  };

  const canManage =
    currentUser?.role === "superadmin" || currentUser?.role === "admin";

  return (
    <div className="mt-16 pt-12 border-t border-neutral-200 dark:border-neutral-800">
      <h3 className="text-3xl font-black text-neutral-900 dark:text-white tracking-tighter mb-8">
        Обсуждение <span className="text-neutral-400">({comments.length})</span>
      </h3>

      {/* Поле ввода (только для резидентов) */}
      {currentUser ? (
        <div className="bg-neutral-50 dark:bg-neutral-900 p-4 rounded-3xl mb-12 flex items-end gap-4 border border-neutral-200 dark:border-neutral-800">
          <div className="w-10 h-10 rounded-full bg-[#FFB800] text-black flex items-center justify-center font-bold text-sm shrink-0 uppercase">
            {currentUser.firstName?.charAt(0) || "U"}
          </div>
          <div className="flex-1">
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Поделитесь своими мыслями..."
              className="w-full bg-transparent resize-none outline-none max-h-32 text-neutral-900 dark:text-white placeholder:text-neutral-400 font-medium"
              rows={2}
            />
          </div>
          <button
            onClick={handleSubmit}
            disabled={!content.trim() || isSubmitting}
            className="p-3 bg-neutral-900 dark:bg-white text-white dark:text-black rounded-full hover:scale-105 transition-all disabled:opacity-50 disabled:hover:scale-100 shrink-0"
          >
            {isSubmitting ? (
              <Loader2 size={20} className="animate-spin" />
            ) : (
              <Send size={20} />
            )}
          </button>
        </div>
      ) : (
        <div className="bg-[#FFB800]/10 border border-[#FFB800]/20 rounded-3xl p-6 mb-12 flex flex-col sm:flex-row items-center justify-between gap-4">
          <p className="text-[#FFB800] font-bold text-sm">
            Оставлять комментарии могут только резиденты общины.
          </p>
          <Link
            href="/sign-in"
            className="px-6 py-2.5 bg-[#FFB800] text-black font-bold text-sm rounded-full transition-transform hover:scale-105 shrink-0"
          >
            Войти в систему
          </Link>
        </div>
      )}

      {/* Список комментариев */}
      <div className="space-y-6">
        {comments.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-neutral-400">
            <MessageSquareOff size={48} className="mb-4 opacity-50" />
            <p className="font-medium text-lg">
              Пока нет комментариев. Будьте первыми!
            </p>
          </div>
        ) : (
          comments.map((comment) => (
            <div key={comment.id} className="flex gap-4 group">
              {/* Аватарка */}
              {comment.user?.imageUrl ? (
                <img
                  src={comment.user.imageUrl}
                  alt="Avatar"
                  className="w-12 h-12 rounded-full object-cover shrink-0"
                />
              ) : (
                <div className="w-12 h-12 rounded-full bg-neutral-200 dark:bg-neutral-800 text-neutral-500 flex items-center justify-center font-bold shrink-0">
                  {comment.user?.firstName?.charAt(0) || "U"}
                </div>
              )}

              <div className="flex-1">
                <div className="flex items-center gap-3 mb-1">
                  <span className="font-bold text-neutral-900 dark:text-white">
                    {comment.user?.firstName} {comment.user?.lastName}
                  </span>
                  <span className="text-xs font-medium text-neutral-400">
                    {new Date(comment.createdAt).toLocaleDateString("ru-RU", {
                      day: "numeric",
                      month: "short",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </span>
                </div>
                <p className="text-neutral-600 dark:text-neutral-300 leading-relaxed font-medium bg-neutral-50 dark:bg-neutral-900/50 p-4 rounded-2xl rounded-tl-sm inline-block">
                  {comment.content}
                </p>

                {/* Кнопка удаления для админов */}
                {canManage && (
                  <button
                    onClick={() => handleDelete(comment.id)}
                    className="ml-3 text-[10px] font-black uppercase tracking-widest text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    Удалить
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

