"use client";

import { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import {
  Check,
  Loader2,
  ArrowRight,
  X,
  Clock,
  Banknote,
  HeartHandshake,
} from "lucide-react";
import {
  registerForService,
  checkServiceRegistration,
} from "@/actions/service";
import { useRouter } from "next/navigation";
import { useServiceRegistrationStore } from "@/store/useServiceRegistration";

export default function PublicServiceCard({
  item,
  userId,
}: {
  item: any;
  userId?: string | null;
}) {
  const { service, category } = item;
  const router = useRouter();

  const [isRegistered, setIsRegistered] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [mounted, setMounted] = useState(false);

  const [showPhoneModal, setShowPhoneModal] = useState(false);
  const [phone, setPhone] = useState("");

  const { setPendingService } = useServiceRegistrationStore();
  const serviceImageUrl =
    service.imageUrl ||
    "https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?q=80&w=800&auto=format&fit=crop";

  useEffect(() => {
    setMounted(true);
    const checkStatus = async () => {
      if (userId) {
        const status = await checkServiceRegistration(service.id, userId);
        setIsRegistered(status);
      }
      setIsLoading(false);
    };
    checkStatus();
  }, [service.id, userId]);

  const handleRegisterClick = () => {
    if (!userId) {
      setPendingService(service.id);
      router.push("/sign-in?redirect_url=/dashboard/my-services");
      return;
    }
    setShowPhoneModal(true);
  };

  const submitRegistration = async () => {
    if (!phone.trim() || !userId) return;
    setIsRegistering(true);
    const res = await registerForService(service.id, userId, phone);
    if (res.success) {
      setIsRegistered(true);
      setShowPhoneModal(false);
    }
    setIsRegistering(false);
  };

  useEffect(() => {
    if (isModalOpen || showPhoneModal) document.body.style.overflow = "hidden";
    else document.body.style.overflow = "unset";
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isModalOpen, showPhoneModal]);

  // МОДАЛКА ВВОДА ТЕЛЕФОНА
  const phoneModalContent = showPhoneModal ? (
    <div
      className="fixed inset-0 z-[10000] flex items-center justify-center bg-black/40 backdrop-blur-md p-4"
      onClick={() => setShowPhoneModal(false)}
    >
      <div
        className="bg-white p-8 rounded-[32px] max-w-sm w-full shadow-2xl animate-in fade-in zoom-in-95 duration-200 border border-neutral-100"
        onClick={(e) => e.stopPropagation()}
      >
        <h3 className="text-2xl font-black text-neutral-900 mb-2 tracking-tighter">
          Ваш контакт
        </h3>
        <p className="text-neutral-500 text-sm mb-6 font-medium">
          Укажите номер телефона для связи с вами.
        </p>
        <input
          type="tel"
          placeholder="+972 5X XXX XXXX"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          className="w-full bg-neutral-50 border-2 border-neutral-200 p-4 rounded-2xl mb-6 focus:border-neutral-900 focus:ring-0 outline-none transition-all font-medium"
          autoFocus
        />
        <div className="flex gap-3 flex-col sm:flex-row">
          <button
            onClick={() => setShowPhoneModal(false)}
